#include "tests/cpp/vst3_command_test_support.hpp"

#include <bit>
#include <chrono>
#include <cmath>
#include <iomanip>
#include <iostream>
#include <limits>
#include <utility>

namespace {
using namespace rhodes;
using namespace rhodes::vst3;
using namespace rhodes::vst3::test_host;
using ScalarEngine = std::remove_cvref_t<
    decltype(std::declval<const HostEventProcessor&>().engine())>;
using Host = ProcessorHost<double, 64>;
constexpr std::size_t frames = 64;
constexpr std::size_t repetitions = 24;
constexpr std::array<const char*, 5> cases{
    "no_commands", "reverse_groups_256", "reverse_interleaved_256",
    "dense_commands_256_notes_256", "rejected_final_command_point"};

float velocity(std::size_t index) {
    return 0.03125F + 0.0078125F * static_cast<float>(index % 4);
}

// Independent scalar-engine oracle: explicit fixture-owned entries, without
// NoteTracker, adapter command sorting, or adapter event dispatch.
struct Oracle {
    struct Owner { bool active = false; std::size_t key = 0; int channel = 0; };
    std::unique_ptr<ScalarEngine> engine = std::make_unique<ScalarEngine>();
    std::array<Owner, 512> owners{};
    std::array<std::size_t, key_count> counts{};
    std::size_t next_owner = 0;
    std::size_t strikes = 0;
    std::size_t releases = 0;

    Oracle() { require(engine->prepare(48000.0), "oracle preparation"); }
    void strike(std::size_t index) {
        const auto key = index % key_count;
        const auto channel = static_cast<int>(index % 16);
        require(next_owner < owners.size(), "oracle owner storage");
        owners[next_owner++] = {true, key, channel};
        ++counts[key];
        ++strikes;
        require(engine->note_on(key, static_cast<double>(velocity(index))), "oracle strike");
    }
    void release(int channel) {
        const auto before = counts;
        for (auto& owner : owners) {
            if (owner.active && owner.channel == channel) {
                --counts[owner.key];
                owner.active = false;
            }
        }
        for (std::size_t key = 0; key < key_count; ++key) {
            if (before[key] > 0 && counts[key] == 0) {
                require(engine->note_off(key), "oracle release");
                ++releases;
            }
        }
    }
    template<class Actions>
    void compare(Host& host, Actions actions) {
        bool nonzero = false;
        for (std::size_t frame = 0; frame < frames; ++frame) {
            actions(frame);
            double sample = 0.0;
            require(engine->process(std::span<double>(&sample, 1)), "oracle process");
            const auto expected = 16.0 * sample;
            require(std::bit_cast<std::uint64_t>(host.left[frame]) ==
                        std::bit_cast<std::uint64_t>(expected) &&
                    std::bit_cast<std::uint64_t>(host.right[frame]) ==
                        std::bit_cast<std::uint64_t>(expected), "scalar audio mismatch");
            nonzero = nonzero || expected != 0.0;
        }
        require(host.output.silenceFlags == (nonzero ? 0U : 3U), "oracle silence flags");
        std::size_t total = 0;
        for (std::size_t key = 0; key < key_count; ++key) {
            require(host.processor.note_tracker().held_count(key) == counts[key],
                    "oracle key ownership");
            total += counts[key];
        }
        require(host.processor.note_tracker().active_count() == total, "oracle holder total");
        require(host.processor.current_state() == InstrumentState{} &&
                host.processor.published_state() == InstrumentState{}, "configuration mismatch");
        require(!host.processor.requires_reset(), "unexpected processor fault");
        same_mechanics(host.processor.engine_processor().engine(), *engine);
    }
};

struct Fixture {
    Host host;
    Oracle oracle;
    EventList notes;
    std::array<CommandQueue, 16> commands;
    CommandChanges changes;
    explicit Fixture(std::size_t kind) {
        // One untimed initialization callback holds exactly 256 identified
        // owners over all 73 physical keys and all 16 MIDI channels.
        notes.count = 256;
        for (std::size_t index = 0; index < 256; ++index) {
            notes.values[index] = note_on(0, static_cast<sdk::int32>(index),
                static_cast<sdk::int16>(28 + index % key_count), velocity(index),
                static_cast<sdk::int16>(index % 16));
        }
        host.data.inputEvents = &notes;
        require(host.processor.process(host.data) == sdk::kResultOk, "prehold callback");
        oracle.compare(host, [&](std::size_t frame) {
            if (frame == 0) {
                for (std::size_t index = 0; index < 256; ++index) { oracle.strike(index); }
            }
        });
        require(host.processor.engine_processor().frame_cursor() == frames, "prehold cursor");
        host.data.inputEvents = nullptr;
        notes.get_calls = 0;
        if (kind != 0) {
            changes.count = 16;
            for (std::size_t queue = 0; queue < 16; ++queue) {
                const auto channel = 15 - queue;
                commands[queue].id = kAllNotesOffBaseId + static_cast<vst::ParamID>(channel);
                commands[queue].count = 16;
                changes.values[queue] = &commands[queue];
                for (std::size_t point = 0; point < 16; ++point) {
                    const auto offset = kind == 1 ? 4 * channel + point / 4 :
                                                           4 * point + channel % 4;
                    commands[queue].values[point] = {static_cast<sdk::int32>(offset), 0.0};
                }
            }
            host.data.inputParameterChanges = &changes;
        }
        if (kind >= 3) {
            notes.count = 256;
            for (std::size_t index = 0; index < 256; ++index) {
                notes.values[index] = note_on(static_cast<sdk::int32>(index / 4),
                    static_cast<sdk::int32>(1000 + index),
                    static_cast<sdk::int16>(28 + (256 + index) % key_count),
                    velocity(256 + index), static_cast<sdk::int16>(index % 16));
            }
            host.data.inputEvents = &notes;
        }
        if (kind == 4) {
            commands.back().values[15].value = std::numeric_limits<double>::quiet_NaN();
        }
        host.fill(0.25);
    }

    void validate(std::size_t kind, sdk::tresult status, const ProcessorSnapshot* before) {
        const std::size_t expected_commands = kind == 0 ? 0 : 256;
        std::size_t reads = 0;
        for (const auto& command : commands) { reads += command.reads; }
        require(reads == expected_commands, "command point read bound");
        require(changes.reads == (kind == 0 ? 0U : 16U), "parameter queue read bound");
        require(notes.get_calls == (kind == 3 ? 256U : 0U), "input event read bound");
        if (kind == 4) {
            require(status == sdk::kResultFalse && before != nullptr, "late rejection status");
            host.expect_silence();
            before->expect_unchanged(host.processor);
            // Longer than the 96-frame filter memory, independently of the
            // snapshot helper's shorter continuation.
            const auto actual = std::make_unique<ScalarEngine>(host.processor.engine_processor().engine());
            const auto expected = std::make_unique<ScalarEngine>(before->engine.engine());
            std::array<double, 128> a{}, b{};
            require(actual->process(a) && expected->process(b) && a == b,
                    "late rejection changed delayed continuation");
            return;
        }
        require(status == sdk::kResultOk, "valid workload rejected");
        oracle.compare(host, [&](std::size_t frame) {
            if (kind != 0) {
                // Ascending channels implement the contract directly. The
                // oracle does not read or sort the host's queue storage.
                for (int channel = 0; channel < 16; ++channel) {
                    if (kind == 1) {
                        if (frame / 4 == static_cast<std::size_t>(channel)) {
                            for (int duplicate = 0; duplicate < 4; ++duplicate) {
                                oracle.release(channel);
                            }
                        }
                    } else if (frame % 4 == static_cast<std::size_t>(channel % 4)) {
                        oracle.release(channel);
                    }
                }
            }
            if (kind == 3) {
                for (std::size_t slot = 0; slot < 4; ++slot) {
                    oracle.strike(256 + 4 * frame + slot);
                }
            }
        });
        require(host.processor.engine_processor().frame_cursor() == 2 * frames, "accepted cursor");
    }
};

std::uint64_t output_hash(const Host& host) {
    std::uint64_t hash = UINT64_C(14695981039346656037);
    for (std::size_t frame = 0; frame < frames; ++frame) {
        for (const auto sample : {host.left[frame], host.right[frame]}) {
            const auto bits = std::bit_cast<std::uint64_t>(sample);
            for (unsigned shift = 0; shift < 64; shift += 8) {
                hash = (hash ^ ((bits >> shift) & UINT64_C(255))) * UINT64_C(1099511628211);
            }
        }
    }
    return hash;
}
} // namespace

int main() {
    try {
        std::cout << "{\"type\":\"metadata\",\"plugin\":\"" << kPluginName
                  << "\",\"processor_bytes\":" << sizeof(RhodesProcessor)
                  << ",\"tracker_bytes\":" << sizeof(NoteTracker)
                  << ",\"host_event_processor_bytes\":" << sizeof(HostEventProcessor)
                  << ",\"clock_is_steady\":" << (std::chrono::steady_clock::is_steady ? "true" : "false")
                  << ",\"repetitions_per_case\":" << repetitions << "}\n";
        std::size_t sequence = 0;
        for (std::size_t repeat = 0; repeat < repetitions; ++repeat) {
            for (std::size_t slot = 0; slot < cases.size(); ++slot) {
                const auto kind = (repeat + slot) % cases.size();
                // All allocation, host setup, fixture generation, snapshotting,
                // and output checks are outside this one-call timer.
                const auto fixture = std::make_unique<Fixture>(kind);
                std::unique_ptr<ProcessorSnapshot> snapshot;
                if (kind == 4) { snapshot = std::make_unique<ProcessorSnapshot>(fixture->host.processor); }
                const auto begin = std::chrono::steady_clock::now();
                const auto status = fixture->host.processor.process(fixture->host.data);
                const auto end = std::chrono::steady_clock::now();
                const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(end - begin).count();
                fixture->validate(kind, status, snapshot.get());
                std::size_t reads = 0;
                for (const auto& command : fixture->commands) { reads += command.reads; }
                std::cout << "{\"type\":\"callback\",\"sequence\":" << sequence++
                          << ",\"repetition\":" << repeat << ",\"case\":\"" << cases[kind]
                          << "\",\"elapsed_ns\":" << elapsed << ",\"status\":" << status
                          << ",\"command_point_reads\":" << reads
                          << ",\"queue_reads\":" << fixture->changes.reads
                          << ",\"event_reads\":" << fixture->notes.get_calls
                          << ",\"active_holders\":" << fixture->host.processor.note_tracker().active_count()
                          << ",\"frame_cursor\":" << fixture->host.processor.engine_processor().frame_cursor()
                          << ",\"physical_strikes\":" << (fixture->oracle.strikes - 256)
                          << ",\"physical_releases\":" << fixture->oracle.releases
                          << ",\"output_fnv1a64\":\"" << std::hex << std::setw(16) << std::setfill('0')
                          << output_hash(fixture->host) << std::dec
                          << "\",\"validated\":true}\n";
            }
        }
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}

